// HasInventoryLot applies the HasEdge predicate on the "inventory_lot" edge.
func HasInventoryLot() predicate.InventoryLotStatusEvent {
	return predicate.InventoryLotStatusEvent(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, InventoryLotTable, InventoryLotColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasInventoryLotWith applies the HasEdge predicate on the "inventory_lot" edge with a given conditions (other predicates).
func HasInventoryLotWith(preds ...predicate.InventoryLot) predicate.InventoryLotStatusEvent {
	return predicate.InventoryLotStatusEvent(func(s *sql.Selector) {
		step := newInventoryLotStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

